                if (opts.command.indexOf('git ls-remote --heads origin test/TS-80') === 0) return '9a7e2aec9a7e2aec9a7e2aec9a7e2aec9a7e2aec\trefs/heads/test/TS-80';
                if (opts.command.indexOf('gh pr list --head test/TS-80') === 0) return '';
