/**
 * Story Test Automation Rework Action
 * Applies review feedback to the Story test PR and re-triggers review.
 */

var configLoader = require('./configLoader.js');
var autoStart = require('./common/autoStart.js');
var prHelper = require('./common/pullRequest.js');
var mergeState = require('./common/mergeState.js');
const { LABELS } = require('./config.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');
var trackersModule = require('./common/trackers.js');

function smLabelForContext(contextId) {
    if (!contextId) return null;
    var map = {
        'story_test_automation_rework': 'sm_story_test_rework_triggered',
        'bug_test_automation_rework': 'sm_bug_test_rework_triggered'
    };
    return map[contextId] || null;
}

// Canonical copy (gh-823/gh-912): the warning:/note: line filter lives in
// common/pullRequest.js once — this delegate keeps every local call site.
function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

function readFile(path) {
    try {
        const content = file_read({ path: path });
        return (content && content.trim()) ? content : null;
    } catch (e) {
        console.warn('Could not read file ' + path + ':', e);
        return null;
    }
}

function runInRepo(command, workingDir) {
    var args = { command: command };
    if (workingDir) args.workingDirectory = workingDir;
    return cli_execute_command(args);
}

// ── gh-1006: pure parse/build/decide helpers extracted from mergeMain ──

function configureGitAuthor(runInRepoFn, config, workingDir) {
    try {
        runInRepoFn('git config user.name "' + config.git.authorName + '"', workingDir);
        runInRepoFn('git config user.email "' + config.git.authorEmail + '"', workingDir);
    } catch (e) {
        console.warn('Could not configure git author:', e);
    }
}

function parseConflictedFiles(statusOutput) {
    return statusOutput.split('\n').map(function(s) { return s.trim(); }).filter(function(s) { return s; });
}

function decideConflictSide(storyKey, file) {
    return file.indexOf('testing/tests/' + storyKey + '/') === 0 ? 'ours' : 'theirs';
}

function buildMergeCommitMessage(storyKey) {
    return storyKey + ' test rework: merge origin/main and resolve test conflicts';
}

function resolveMergeConflicts(runInRepoFn, workingDir, storyKey) {
    var status = cleanCommandOutput(runInRepoFn('git diff --name-only --diff-filter=U', workingDir) || '');
    var conflicts = parseConflictedFiles(status);
    if (conflicts.length === 0) {
        throw new Error('git merge origin/main failed and no conflicted files were found');
    }

    conflicts.forEach(function(file) {
        try {
            if (decideConflictSide(storyKey, file) === 'ours') {
                runInRepoFn('git checkout --ours -- "' + file + '"', workingDir);
                console.log('✅ Resolved conflict keeping branch version for ticket test file:', file);
            } else {
                runInRepoFn('git checkout --theirs -- "' + file + '"', workingDir);
                console.log('✅ Resolved conflict keeping origin/main version:', file);
            }
            runInRepoFn('git add "' + file + '"', workingDir);
        } catch (e) {
            throw new Error('Failed to resolve conflict for ' + file + ': ' + e);
        }
    });
}

function commitResolvedMerge(runInRepoFn, workingDir, storyKey) {
    try {
        runInRepoFn('git commit -m "' + buildMergeCommitMessage(storyKey).replace(/"/g, '\\"') + '"', workingDir);
        console.log('✅ Committed merge with auto-resolved test conflicts');
    } catch (e) {
        throw new Error('Failed to commit auto-resolved merge: ' + e);
    }
}

function mergeMain(storyKey, config) {
    var workingDir = config.workingDir || null;

    // gh-761: never start a merge on top of an unconcluded one. When
    // MERGE_HEAD exists (the agent left a conflicted base-branch merge
    // unresolved), the old flow finalized that FOREIGN merge: `git merge
    // origin/main` failed with "You have not concluded your merge", the
    // fallback then read the LEFTOVER unmerged paths, auto-resolved them
    // with --ours/--theirs and committed — baking conflict markers into a
    // merge nobody deliberately resolved. Refuse with an actionable error
    // instead; the job fails visibly and the tree stays exactly as the
    // agent left it.
    if (mergeState.isMergeInProgress(runInRepo, workingDir)) {
        throw new Error('mergeMain: a merge is already in progress (MERGE_HEAD exists) in ' +
            (workingDir || '.') + ' — conclude or abort the unconcluded merge before rework can merge origin/main for ' + storyKey);
    }

    configureGitAuthor(runInRepo, config, workingDir);

    console.log('Fetching origin/main to keep test branch up to date...');
    try {
        runInRepo('git fetch origin main', workingDir);
    } catch (e) {
        throw new Error('Failed to fetch origin/main: ' + e);
    }

    console.log('Unshallowing repository so git merge can find merge base...');
    try {
        runInRepo('git fetch --unshallow', workingDir);
    } catch (e) {
        console.warn('Unshallow fetch failed (may already be complete):', e);
    }

    var mergeOutput = '';
    try {
        mergeOutput = cleanCommandOutput(runInRepo('git merge origin/main --no-edit', workingDir) || '');
        console.log('✅ Merged origin/main into test branch');
        return;
    } catch (mergeError) {
        var mergeErrStr = (mergeError && mergeError.toString ? mergeError.toString() : String(mergeError)) + ' ' + mergeOutput;
        console.warn('git merge origin/main failed:', mergeErrStr);
        console.warn('Attempting auto-resolution for ticket test files...');
    }

    resolveMergeConflicts(runInRepo, workingDir, storyKey);
    commitResolvedMerge(runInRepo, workingDir, storyKey);
}

function commitAndPush(storyKey, config) {
    var workingDir = config.workingDir || null;
    var branchName = cleanCommandOutput(runInRepo('git branch --show-current', workingDir) || '');
    if (!branchName) throw new Error('Could not determine current git branch');
    if (branchName === 'main' || branchName === 'master') {
        throw new Error('Refusing to commit rework directly to "' + branchName + '". Expected test/' + storyKey);
    }

    console.log('Current branch:', branchName);
    mergeMain(storyKey, config);
    runInRepo('git config user.name "' + config.git.authorName + '"', workingDir);
    runInRepo('git config user.email "' + config.git.authorEmail + '"', workingDir);
    runInRepo('git add testing/', workingDir);

    var statusOutput = cleanCommandOutput(runInRepo('git diff --cached --stat', workingDir) || '');
    if (statusOutput.trim()) {
        var commitMsg = configLoader.formatTemplate(config.formats.commitMessage.testRework, {
            ticketKey: storyKey,
            result: 'address review comments'
        });
        runInRepo('git commit -m "' + commitMsg.replace(/"/g, '\\"') + '"', workingDir);
        console.log('✅ Committed rework changes');
    } else {
        console.warn('No changes to commit in testing/ — pushing existing commits only');
    }

    try {
        runInRepo('git push -u origin ' + branchName, workingDir);
    } catch (e) {
        console.log('Normal push failed, force pushing...');
        runInRepo('git push -u origin ' + branchName + ' --force', workingDir);
    }

    var remoteBranchExists = false;
    try {
        // gh-912: verify the push produced a real refs/heads/<branch> ref
        // line — stderr noise never counts as the branch existing.
        remoteBranchExists = prHelper.remoteBranchExists(runInRepo, workingDir, branchName);
    } catch (lsRemoteErr) {
        console.warn('Error checking remote branches:', lsRemoteErr);
    }
    if (!remoteBranchExists) throw new Error('Branch not found on remote after push');
    console.log('✅ Pushed to remote branch:', branchName);
    return branchName;
}

// ── gh-1006: pure parse/build/decide helpers extracted from postThreadReplies ──

// Returns the reply list to process, or null when there is nothing to do
// (missing file, unparseable JSON, or empty li…

/**
 * Post Story Test Automation Results Action
 * 1. Reads outputs/story_test_automation_result.json
 * 2. Commits/pushes testing/ folder on test/{STORY_KEY} branch
 * 3. Creates PR to main
 * 4. Per linked Test Case:
 *    - status → In Review - Passed / In Review - Failed
 *    - failed TC: attach outputs/failed_description_{TC_KEY}.md and set Failed Reason field
 * 5. Moves Story → In Testing
 * 6. Triggers pr_story_test_automation_review
 *
 * gh-1008 CRAP split: tracker/git/marker/wiki helpers live in
 * js/postStoryTestAutomationShared.js; action() is a thin orchestrator.
 */

var configLoader = require('./configLoader.js');
var prHelper = require('./common/pullRequest.js');
var autoStart = require('./common/autoStart.js');
const { GIT_CONFIG, LABELS, JIRA_FIELDS } = require('./config.js');
var outputFiles = require('./common/outputFiles.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');
var shared = require('./postStoryTestAutomationShared.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var trackerHolder = shared.createTrackerHolder(trackersModule);
function initTracker(config, customParams) {
    trackerHolder.initTracker(config, customParams);
}
function getTracker() {
    return trackerHolder.getTracker();
}

var gitOps = shared.createGitOps(prHelper);
var runInRepo = shared.runInRepo;

var RESUME_MARKER = 'outputs/.story-test-resume-attempted';

function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

function readFile(path) {
    return outputFiles.readOutputFile(path, {});
}

function readOutputFile(relativePath, workingDir, ticketKey) {
    return outputFiles.readOutputFile(relativePath, {
        workingDir: workingDir,
        ticketKey: ticketKey
    });
}

function readResultJson(workingDir, storyKey) {
    try {
        const raw = readOutputFile('story_test_automation_result.json', workingDir, storyKey);
        if (!raw) {
            console.warn('outputs/story_test_automation_result.json is empty or missing');
            return null;
        }
        const rawString = String(raw);
        try {
            const parsed = JSON.parse(rawString);
            console.log('Story test result overall:', parsed.overall);
            return parsed;
        } catch (parseErr) {
            console.error('Failed to parse story_test_automation_result.json:', parseErr);
            console.error('Raw content preview (first 1000 chars):', rawString.substring(0, 1000));
            console.error('Raw content preview around error:', rawString.substring(Math.max(0, parseErr.pos - 100), parseErr.pos + 100));
            return null;
        }
    } catch (e) {
        console.error('Failed to read story_test_automation_result.json:', e);
        return null;
    }
}

function readLinkedTestCases(storyKey, testCaseType) {
    try {
        var raw = readFile('input/' + storyKey + '/linked_test_cases.json');
        if (raw) {
            var parsed = JSON.parse(raw);
            if (parsed && Array.isArray(parsed.testCases)) {
                console.log('Loaded', parsed.testCases.length, 'linked Test Case(s) from input folder');
                return parsed.testCases;
            }
        }
    } catch (e) {
        console.warn('Could not read linked_test_cases.json, falling back to JQL:', e);
    }

    try {
        var jql = 'issue in linkedIssues("' + storyKey + '") AND issuetype = "' + testCaseType + '"';
        // JQL text: provider-specific query (WIQL on ado)
        var results = getTracker().searchIssues(jql, { maxResults: 100, fields: ['key'] });
        return Array.isArray(results) ? results : [];
    } catch (e) {
        console.warn('Failed to fetch linked Test Cases from Jira:', e);
        return [];
    }
}

function getMissingTestCaseKeys(result, linkedTestCases) {
    var resultKeys = {};
    if (result && Array.isArray(result.results)) {
        result.results.forEach(function(r) {
            if (r.testCaseKey) resultKeys[r.testCaseKey] = true;
        });
    }
    return linkedTestCases
        .map(function(tc) { return tc.key; })
        .filter(function(key) { return key && !resultKeys[key]; });
}

function buildResumePrompt(storyKey, linkedTestCases, result, missingKeys) {
    var checkedKeys = [];
    if (result && Array.isArray(result.results)) {
        checkedKeys = result.results.map(function(r) { return r.testCaseKey; }).filter(Boolean);
    }

    var resultSchema = JSON.stringify({
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "required": ["storyKey", "overall", "summary", "results"],
        "properties": {
            "storyKey": { "type": "string", "const": storyKey },
            "overall": { "type": "string", "enum": ["passed", "failed", "in_progress"] },
            "summary": { "type": "string" },
            "results": {
                "type": "array",
                "items": {
                    "type": "object",
                    "required": ["testCaseKey", "status"],
                    "properties": {
                        "testCaseKey": { "type": "string", "pattern": "^TS-[0-9]+$" },
                        "status": { "type": "string", "enum": ["passed", "failed", "skipped", "irrelevant"] },
                        "testPath": { "type": "string" },
                        "failedDescriptionFile": { "type": "string" },
                        "failureSummary": { "type": "string" }
                    },
                    "additionalProperties": false
                }
            }
        },
        "additionalProperties": false
    }, null, 2);

    return 'RESUME TASK: The previous story test automation run did not verify all linked Test Cases.\n\n' +
        'Story: ' + storyKey + '\n' +
        'Linked Test Cases (' + linkedTestCases.length + '): ' + linkedTestCases.map(function(tc) { return tc.key; }).join(', ') + '\n' +
        'Already checked (' + checkedKeys.length + '): ' + (checkedKeys.join(', ') || 'none') + '\n' +
        'Still missing (' + missingKeys.length + '): ' + missingKeys.join(', ') + '\n\n' +
        'Instructions:\n' +
        '- Continue the same story test automation task in the same repository.\n' +
        '- For every missing Test Case, run/verify the corresponding automated test.\n' +
        '- Create or update outputs/story_test_automation_result.json with a top-level object that matches the JSON Schema below.\n' +
        '- Append a result entry for each missing Test Case:\n' +
        '  { "testCaseKey": "TS-XXX", "status": "passed" | "failed" | "skipped" | "irrelevant", "testPath": "testing/tests/TS-XXX/...", "failedDescriptionFile": "outputs/failed_description_TS-XXX.md", "failureSummary": "..." }\n' +
        '- If the result JSON file is missing, create it from scratch using the existing outputs/response.md and testing/tests/ files as evidence.\n' +
        '- If a test fails, write a failed description file and reference it in the result entry.\n' +
        '- Do NOT push changes; the post-action will commit and push after you finish.\n' +
        '- Do NOT move the Story to another status.\n' +
        '- Update outputs/response.md with a short summary of what was verified.\n' +
        '- Validate that outputs/story_test_automation_result.json is parseable JSON that conforms to the schema before stopping.\n\n' +
        'Required JSON schema for outputs/story_test_automation_result.json:\n' + resultSchema + '\n';
}

function attemptResumeIfOutputsIncomplete(storyKey, result, linkedTestCases, workingDir) {
    var missingKeys = getMissingTestCaseKeys(result, linkedTestCases);
    if (missingKeys.length === 0) {
        return { attempted: false, reason: 'complete' };
    }

    var attempt = shared.readAttemptMarker(RESUME_MARKER);
    var maxAttempts = 2;
    if (attempt >= maxAttempts) {
        console.warn('Story test resume attempts exhausted (' + attempt + '/' + maxAttempts + '). Missing TCs:', missingKeys.join(', '));
        return { attempted: false, reason: 'attempts-exhausted', missingKeys: missingKeys };
…

/**
 * Check Story Tests Passed — postJSAction for story_done_check agent.
 *
 * Runs on every SM cycle for each Story in "In Testing".
 * - If all linked Test Cases are "Passed" → moves the Story to "Done".
 * - If any linked Test Case is still in an in-flight review/automation status
 *   (In Review - Passed/Failed, In Development, etc.) → releases the lock and
 *   waits for the review/merge/automation agents to finish.
 * - If any linked Test Case is "Failed" and has no linked non-Done bug → waits
 *   for bulk_bugs_creation to create/link the bug.
 * - If any linked Test Case has a linked non-Done bug → moves the Story to
 *   "Bug To Fix" so the bug-fix pipeline can run.
 * - Otherwise all non-passed Test Cases are ready for re-test (bugs Done or no
 *   bugs) → moves the Story back to "Ready For Testing" to trigger a re-run.
 */

const configLoader = require('./configLoader.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');
const trackersModule = require('./common/trackers.js');

function action(params) {
    const ticketKey = params.ticket && params.ticket.key;
    const customParams = params.jobParams && params.jobParams.customParams;
    const removeLabel = customParams && customParams.removeLabel;
    const projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
    const jiraConfig = projectConfig.jira;
    const tracker = trackersModule.createTracker(projectConfig, customParams || {});
    // Legacy override channel: customParams.customStatuses still wins over .dmtools/config.js statuses
    const statuses = Object.assign({}, jiraConfig.statuses, (customParams && customParams.customStatuses) || {});
    const testCaseType = jiraConfig.issueTypes.TEST_CASE || 'Test Case';
    const bugType = jiraConfig.issueTypes.BUG || 'Bug';

    function releaseLock() {
        if (ticketKey && removeLabel) {
            try {
                tracker.removeLabel(ticketKey, removeLabel);
                console.log('Released SM label — will re-check next cycle');
            } catch (e) {
                console.warn('Failed to remove SM label:', e);
            }
        }
    }

    function findLinkedTCs() {
        try {
            // JQL text: provider-specific query (WIQL on ado)
            // gh-916: in label mode the stage gates also read markers, so labels are requested;
            // 'none' mode sends the exact same fields list as before.
            var fields = ['key', 'status'];
            if (tracker.stageFallback() === 'label') fields = fields.concat(['labels']);
            return tracker.searchIssues('issue in linkedIssues("' + ticketKey + '") AND issuetype = "' + testCaseType + '"', {
                fields: fields,
                maxResults: 100
            }) || [];
        } catch (e) {
            console.warn('Failed to fetch linked Test Cases:', e);
            return [];
        }
    }

    function findLinkedBugs(tcKey) {
        try {
            // JQL text: provider-specific query (WIQL on ado)
            return tracker.searchIssues('issue in linkedIssues("' + tcKey + '") AND issuetype = "' + bugType + '"', {
                fields: ['key', 'status'],
                maxResults: 50
            }) || [];
        } catch (e) {
            console.warn('Failed to fetch linked bugs for', tcKey, e);
            return [];
        }
    }

    function findPendingBugKey(tcKey) {
        var bugs = findLinkedBugs(tcKey);
        for (var i = 0; i < bugs.length; i++) {
            var status = bugs[i].fields && bugs[i].fields.status && bugs[i].fields.status.name;
            if (status !== statuses.DONE) {
                return bugs[i].key;
