export function tokenizeSource(source, ext) {
  const { tokens } = parseTokenized(source, ext);
  return tokens
    .filter((t) => t.type.label !== 'eof' && !isCommentToken(t))
    .map((t) => ({ value: source.slice(t.start, t.end), line: t.loc.start.line }));
}

