function loadReworkWith(autoStartModule, scmFactory, mocks, tokenUsageModule) {
    var allMocks = Object.assign({
        cli_execute_command: function () { return ''; },
        file_read: function () { return null; },
        file_write: function () {}
    }, mocks || {});
