            if (configuredBehavior === 'throw') throw new Error('workflow dispatch down');
            return true;
        },
        triggerSmIfIdle: function (opts) {
            this.smIdleCalls.push(opts);
            if (configuredBehavior === 'sm-throws') throw new Error('sm down');
