            if (prFound) comment += '*Pull Request*: ' + prFound.html_url + '\n';
            comment += '\n' + fixSummary;
            tracker.postComment(storyKey, comment);
        } catch (e) {
            console.warn('Failed to post Jira comment:', e);
        }
    }

