const fs = require('fs');
// Extract a top-level (or nested) function's source by name via brace matching.
function extractFn(src, name) {
  const re = new RegExp('function\\\\s+' + name + '\\\\s*\\\\(', 'g');
  let m;
  while ((m = re.exec(src)) !== null) {
    let i = src.indexOf('{', m.index);
    if (i === -1) continue;
    let depth = 0;
    for (let j = i; j < src.length; j++) {
      if (src[j] === '{') depth++;
      else if (src[j] === '}') { depth--; if (depth === 0) return src.slice(m.index, j + 1); }
    }
  }
  return null;
}
const norm = (s) => (s || 'MISSING').split('\n').map(l => l.trim()).filter(l => l && !l.startsWith('//') && !l.startsWith('*') && !l.startsWith('/*')).join('\n');
const [origFile, newFile, ...names] = process.argv.slice(1);
const orig = fs.readFileSync(origFile, 'utf8');
const neu = fs.readFileSync(newFile, 'utf8');
for (const n of names) {
  const a = norm(extractFn(orig, n));
  const b = norm(extractFn(neu, n));
  console.log((a === b ? 'SAME  ' : 'DIFF  ') + n);
  if (a !== b) {
    // find first differing line
    const al = a.split('\n'), bl = b.split('\n');
    for (let k = 0; k < Math.max(al.length, bl.length); k++) {
      if (al[k] !== bl[k]) { console.log('  orig:', JSON.stringify(al[k])); console.log('  new :', JSON.stringify(bl[k])); break; }
    }
