        console.error('Git operations failed:', e);
        tracker.postComment(storyKey, 'h3. ❌ Story Test Rework Push Failed\n\n{code}' + e.toString() + '{code}'
        );
        releaseWipLock();
        return { success: false, error: e.toString() };
    }

