const fs = require('fs');
function parseReport(file) {
  const out = {};
  for (const l of fs.readFileSync(file, 'utf8').split('\n')) {
    const m = l.match(/^(\S+)\s+(\S+)\s+(\d+)\s+([\d.]+%|N\/A)\s+([\d.]+|N\/A)\s*$/);
    if (!m) continue;
    const name = m[1], f = m[2], crap = parseFloat(m[5]);
    if (isNaN(crap)) continue;
    if (/\/(unit-tests|integration-tests|test)\//.test(f)) continue;  // product code only, same as CI badges
    out[f + '::' + name] = crap;
  }
  return out;
}
const before = parseReport('/tmp/before-crap.txt');
const after = parseReport('/tmp/after-crap.txt');
let regressed = [], improved = [], newFns = [];
for (const k of Object.keys(after)) {
  if (!(k in before)) { newFns.push([k, after[k]]); continue; }
  if (after[k] > before[k] + 0.05) regressed.push([k, before[k], after[k]]);
  else if (after[k] < before[k] - 0.05) improved.push([k, before[k], after[k]]);
}
const maxBefore = Math.max(...Object.values(before));
const maxAfter = Math.max(...Object.values(after));
const cnt = (o) => Object.values(o).filter(v => v > 8).length;
console.log('functions: before', Object.keys(before).length, 'after', Object.keys(after).length, '(new:', newFns.length + ')');
