const fs = require('fs');
function parseReport(file) {
  const out = {};
  for (const l of fs.readFileSync(file, 'utf8').split('\n')) {
    const m = l.match(/^(\S+)\s+(\S+)\s+(\d+)\s+([\d.]+%|N\/A)\s+([\d.]+|N\/A)\s*$/);
    if (!m) continue;
    const name = m[1], f = m[2], crap = parseFloat(m[5]);
    if (isNaN(crap)) continue;
    if (/\/(unit-tests|integration-tests|test)\//.test(f)) continue;  // product code only, same as CI badges
    out[f + '::' + name] = crap;
  }
  return out;
}
